// getOrCreateCredentials serializes CSR requests per authenticated identity.
// A cached certificate must have at least one minute of validity remaining.
func (f *Forwarder) getOrCreateCredentials(ctx authContext) (*tls.Config, error) {
	if config := f.getCredentials(ctx); config != nil {
		return config, nil
	}
	requestCtx, done := f.getOrCreateRequestContext(ctx.key())
	if done != nil {
		defer done()
		// Another request may have populated the cache before this lock was taken.
		if config := f.getCredentials(ctx); config != nil {
			return config, nil
		}
		config, err := f.requestCertificate(ctx)
		if err != nil {
			return nil, trace.Wrap(err)
		}
		if err := f.credentials.Set(ctx.key(), config, ctx.sessionTTL); err != nil {
			return nil, trace.Wrap(err)
		}
		return config, nil
	}
	select {
	case <-requestCtx.Done():
		if config := f.getCredentials(ctx); config != nil {
			return config, nil
		}
		return nil, trace.BadParameter("failed to request certificate, try again")
	case <-f.ctx.Done():
		return nil, trace.BadParameter("forwarder is closing, aborting the request")
	}
}

func (f *Forwarder) getCredentials(ctx authContext) *tls.Config {
	if f.credentials == nil {
		return nil
	}
	cached, ok := f.credentials.Get(ctx.key())
	if !ok {
		return nil
	}
	config := cached.(*tls.Config)
	if len(config.Certificates) == 0 || len(config.Certificates[0].Certificate) == 0 {
		return nil
	}
	cert, err := x509.ParseCertificate(config.Certificates[0].Certificate[0])
	if err != nil || cert.NotAfter.Before(f.Clock.Now().Add(time.Minute)) {
		f.credentials.Remove(ctx.key())
		return nil
	}
	return config
}

